""" Generate sequence (that unlike xrange supports float)

    max: defines the sequence maximum
    step: defines the interval
    """
def _generate_Sequence(min: Any, max: Any, step: Any) -> object {
    i = min;
    I = [];
    while (i <= max) {
        I.append(i);
        i = i + step;
    }
    return I;
}

""" Format the path for the storage of a verification object
    Args:
        l1_block_id: the id of the L1 block which this verification verifies
        level_received_from: the level from which this verification was received
        chain_id: the internal id of the chain who sent this verification
    Returns:
        path: the formatted path
    """
def verification_storage_location(
    l1_block_id: str, level_received_from: int, chain_id: str
) -> str {
    return f"BLOCK/{l1_block_id}-l{level_received_from}-{chain_id}";
}

"""
    Parameters
    ----------
    string String representation of a list

    Returns A List
    -------

    """
def str_to_list(string: Any) -> object {
    if ("[" and ("]" in string)) {
        string = string[1:-1];
        spt = string.split(",");
        lis = [];
        for f in spt {
            lis.append(float(f));
        }
        return lis;
    }
    return [];
}

