"""Return True if there are no duplicates elements in slice s[start:stop]."""
def unique3(s: Any, start: Any, stop: Any) -> object {
    if ((stop - start) <= 0) {
        return True;
    } elif not unique3(s, start, (stop - 1)) {
        return False;
    } elif not unique3(s, (start + 1), stop) {
        return False;
    } else {
        return (s[start] != s[(stop - 1)]);
    }
}

"""Dot product of two equal-dimensioned vectors"""
def dotp(a: Any, b: Any) -> object {
    return sum((aterm * bterm) for (aterm, bterm) in zip(a, b));
}

